// Boundary choices apply to the current-driven physical model, never resistance/temperature curves.
export const supportsZeroOrigin=c=>['Id','If'].some(k=>[c?.xName,c?.yName].includes(k))&&['Vds','Vsd','Vf','Eon','Eoff','Err'].some(k=>[c?.xName,c?.yName].includes(k));
const cache=new WeakMap();
export function boundaryCurve(c){if(!c||!Array.isArray(c.iterations))return c;const old=cache.get(c);if(old?.iterations===c.iterations&&old.policy===c.originPolicy)return old.value;const currentAxis=['Id','If'].includes(c.xName)?'x':'y',other=currentAxis==='x'?'y':'x';const force=c.originPolicy==='zero'&&supportsZeroOrigin(c);const value={...c,iterations:c.iterations.map(it=>{const seen=new Set(),keep=it.x.map((v,j)=>{const key=v+':'+it.y[j];if(seen.has(key)||(force&&it[currentAxis][j]===0))return null;seen.add(key);return j;}).filter(j=>j!==null);return {...it,x:[...(force?[0]:[]),...keep.map(j=>it.x[j])],y:[...(force?[0]:[]),...keep.map(j=>it.y[j])]};})};cache.set(c,{iterations:c.iterations,policy:c.originPolicy,value});return value;}
